    "Premi Esc in qualsiasi momento per interrompere.",
  "Let Claudex see and act in the apps you allow, working in the background or with full control of your screen. Screenshots of those apps are sent to the model.":
    "Consenti a Claudex di vedere e utilizzare le app autorizzate, lavorando in background o con il controllo completo dello schermo. Gli screenshot di queste app vengono inviati al modello.",
  "Background: Claudex works inside the apps you allow while you keep using your computer, and asks your permission before taking full control of your screen. Full control: Claudex takes control of your screen, mouse, and keyboard by default whenever Claudex uses an app you allow, without asking again.":
    "Background: Claudex lavora nelle app autorizzate mentre continui a usare il computer e chiede il tuo permesso prima di assumere il controllo completo dello schermo. Controllo completo: quando usa un’app autorizzata, Claudex assume per impostazione predefinita il controllo di schermo, mouse e tastiera senza chiedere di nuovo.",
  "Claudex uses your computer's OpenSSH. Passwords are never saved; use an SSH key and ssh-agent to connect without prompts.":
    "Claudex usa OpenSSH del tuo computer. Le password non vengono mai salvate; usa una chiave SSH e ssh-agent per connetterti senza richieste.",
  "Run Code sessions on another computer over SSH. Claudex uses this computer's OpenSSH and your SSH keys; passwords are never saved.":
    "Esegui sessioni Code su un altro computer tramite SSH. Claudex usa OpenSSH di questo computer e le tue chiavi SSH; le password non vengono mai salvate.",
