  "Added. It also uses {services}, which need signing in before Claudex can use them.":
    "Aggiunto. Usa anche {services}, a cui devi accedere prima che Claudex possa utilizzarli.",
  "Make sure you trust a plugin before installing, updating, or using it. Plugins installed from marketplaces are not controlled by Anthropic, and Anthropic cannot verify that they will work as intended or that they won't change. See each plugin's homepage for more information.":
    "Assicurati di fidarti di un plugin prima di installarlo, aggiornarlo o usarlo. I plugin installati dai marketplace non sono controllati da Anthropic, che non può verificare che funzionino come previsto o che non cambino. Per ulteriori informazioni consulta la homepage di ciascun plugin.",
  "Updated tasks · {done} of {total} done":
    "Attività aggiornate · {done} completate su {total}",
  "Bypass all permission checks and let Claudex work uninterrupted in folders you confirm. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Ignora tutti i controlli delle autorizzazioni e lascia che Claudex lavori senza interruzioni nelle cartelle che confermi. È utile per attività come correggere errori di lint o generare codice standard. Consentire a Claudex di eseguire comandi arbitrari è rischioso e può causare perdita di dati, danneggiamento del sistema o esfiltrazione di dati, ad esempio tramite attacchi di prompt injection.",
  "How Claudex structures its responses in Code sessions. Applies to new sessions; the session menu can override it for a single session.":
    "Il modo in cui Claudex struttura le risposte nelle sessioni Code. Si applica alle nuove sessioni; il menu della sessione può modificarlo per una singola sessione.",
