  "Afternoon, {name}": "Pomeriggio, {name}",
  "Career chat": "Carriera & lavoro",
  "Prepare for an interview": "Prepararmi a un colloquio",
  "Help me prepare for a job interview. I'll share the role and my background, then you ask me likely questions one at a time and give feedback on each answer.":
    "Aiutami a prepararmi a un colloquio di lavoro. Ti descrivo il ruolo e il mio percorso, poi mi fai le domande più probabili una alla volta e mi dai un riscontro su ogni risposta.",
  "Sharpen my resume": "Migliorare il mio curriculum",
  "Read my resume, point out what's unclear or missing, then rewrite the weakest parts so my results stand out. Here it is:\n\n":
    "Leggi il mio curriculum, indica cosa non è chiaro o manca, poi riscrivi le parti più deboli perché i miei risultati risaltino. Eccolo:\n\n",
  "Rehearse a hard conversation": "Provare una conversazione difficile",
  "Role-play a conversation I need to have at work. I'll tell you who it's with and what I want to say; you play them realistically, then tell me what worked.":
    "Facciamo un gioco di ruolo su una conversazione che devo affrontare al lavoro. Ti dico con chi è e cosa voglio dire; tu interpreti quella persona in modo realistico, poi mi dici cosa ha funzionato.",
  "Map my next career step": "Tracciare il prossimo passo di carriera",
  "Help me plan my next career step. Ask me what I do now, what I enjoy and where I'd like to be, then suggest a few paths and what each would take.":
    "Aiutami a pianificare il mio prossimo passo di carriera. Chiedimi cosa faccio ora, cosa mi piace e dove vorrei arrivare, poi suggeriscimi alcuni percorsi e cosa richiederebbe ciascuno.",
  "Handle a tricky work situation": "Gestire una situazione delicata al lavoro",
