  "Workspace trust isn't available here.":
    "L’attendibilità dell’area di lavoro non è disponibile qui.",
  "Saving your work": "Salvataggio del tuo lavoro",
  "Uploading your work": "Caricamento del tuo lavoro",
  "Claudex picks up where you left off in a new cloud session, with your work exactly as it is now.":
    "Claudex riprende da dove avevi lasciato in una nuova sessione cloud, con il tuo lavoro esattamente com’è ora.",
  "1 uncommitted change comes along.":
    "1 modifica non sottoposta a commit viene inclusa.",
  "{count} uncommitted changes come along.":
    "{count} modifiche non sottoposte a commit vengono incluse.",
  "1 unpushed commit rides along.": "1 commit non inviato viene incluso.",
  "{count} unpushed commits ride along.":
    "{count} commit non inviati vengono inclusi.",
  "Your work is uploaded to {repo} on GitHub. Nothing is pushed to your branch.":
    "Il tuo lavoro viene caricato su {repo} su GitHub. Nulla viene inviato al tuo branch.",
  "It starts from {branch}.": "Parte da {branch}.",
  "1 untracked file stays on this computer because it looks like a secret or is over 10 MB: {names}. Stage a file with git add to bring it along.":
    "1 file non tracciato resta su questo computer perché sembra un segreto o supera i 10 MB: {names}. Aggiungi un file all’area di staging con git add per includerlo.",
  "{count} untracked files stay on this computer because they look like secrets or are over 10 MB: {names}. Stage a file with git add to bring it along.":
    "{count} file non tracciati restano su questo computer perché sembrano segreti o superano i 10 MB: {names}. Aggiungi un file all’area di staging con git add per includerlo.",
  "1 file can’t be moved safely, so it stays on this computer: {names}.":
    "1 file non può essere spostato in sicurezza, quindi resta su questo computer: {names}.",
  "{count} files can’t be moved safely, so they stay on this computer: {names}.":
    "{count} file non possono essere spostati in sicurezza, quindi restano su questo computer: {names}.",
  "A {operation} is in progress in this folder. Finish or abort it, then check again.":
    "In questa cartella è in corso un {operation}. Completalo o annullalo, poi ricontrolla.",
  "A git operation is in progress in this folder. Finish or abort it, then check again.":
    "In questa cartella è in corso un’operazione git. Completala o annullala, poi ricontrolla.",
  "This folder has unresolved merge conflicts. Resolve them, or ask Claudex to, then check again.":
    "Questa cartella ha conflitti di merge non risolti. Risolvili, o chiedi a Claudex di farlo, poi ricontrolla.",
  "{count} untracked files here aren’t ignored by git ({dirs}), which is more than a move can carry. Add them to .gitignore, or continue without untracked files.":
    "{count} file non tracciati qui non sono ignorati da git ({dirs}): più di quanti uno spostamento possa portare. Aggiungili a .gitignore o continua senza i file non tracciati.",
  "{count} untracked files here aren’t ignored by git, which is more than a move can carry. Add them to .gitignore, or continue without untracked files.":
    "{count} file non tracciati qui non sono ignorati da git: più di quanti uno spostamento possa portare. Aggiungili a .gitignore o continua senza i file non tracciati.",
  "Continue without untracked files": "Continua senza file non tracciati",
  "Ask Claudex to push": "Chiedi a Claudex di eseguire il push",
  "Asked Claudex to push your work. This comes back when the turn is done.":
    "È stato chiesto a Claudex di inviare il tuo lavoro. Questo tornerà al termine del turno.",
  "Session now in the cloud. The session on this computer stays until you archive it.":
    "La sessione è ora nel cloud. La sessione su questo computer resta finché non la archivi.",
  "This repository has no remote named origin, so there’s nowhere to upload your work. Add one, then try again.":
    "Questo repository non ha un remote chiamato origin, quindi non c’è dove caricare il tuo lavoro. Aggiungine uno, poi riprova.",
  "Your work is uploaded, but the cloud session couldn’t be started right now. Try again in a moment.":
    "Il tuo lavoro è stato caricato, ma al momento non è stato possibile avviare la sessione cloud. Riprova tra poco.",
