  "Automatically archive desktop sessions when the associated pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept.":
    "Archivia automaticamente le sessioni desktop quando la pull request associata viene unita o chiusa. Dopo l’unione, l’archiviazione rimuove anche il worktree della sessione ed elimina il suo branch. Il lavoro non inviato viene conservato.",
  "Archive this session when its pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept. This session only; other sessions follow the default in Settings → Claudex Code.":
    "Archivia questa sessione quando la sua pull request viene unita o chiusa. Dopo l’unione, l’archiviazione rimuove anche il worktree della sessione ed elimina il suo branch. Il lavoro non inviato viene conservato. Solo questa sessione; le altre seguono l’impostazione predefinita in Impostazioni → Claudex Code.",
  "Git won’t check out a branch in two folders at once. Run git worktree list in the repository to see which folder has this branch, switch that folder to a different branch, then try again.":
    "Git non consente di avere lo stesso branch in due cartelle contemporaneamente. Esegui git worktree list nel repository per vedere quale cartella usa questo branch, passa quella cartella a un altro branch e riprova.",
