  "Already installed and open in its own window.":
    "Già installato e aperto in una finestra dedicata.",
  "This browser isn’t offering to install this artifact here. If you’ve installed it, open it from your desktop or app launcher. If this is a private window, open the page in a regular window.":
    "Questo browser non offre l’installazione di questo artefatto qui. Se l’hai già installato, aprilo dal desktop o dall’avvio applicazioni. Se questa è una finestra privata, apri la pagina in una finestra normale.",
