  Standard: "Standard",
  "Your next response will be slower and use more tokens. This task is cached for the current model. Switching to <bold>{targetLabel}</bold> means the full history gets re-read on your next message.":
    "La prossima risposta sarà più lenta e userà più token. Questa attività è memorizzata nella cache per il modello attuale. Passando a <bold>{targetLabel}</bold>, l’intera cronologia verrà riletta al prossimo messaggio.",
  "Your next response will be slower and use more tokens. This task is cached for the current effort level. Switching to <bold>{targetLabel}</bold> means the full history gets re-read on your next message.":
    "La prossima risposta sarà più lenta e userà più token. Questa attività è memorizzata nella cache per il livello di impegno attuale. Passando a <bold>{targetLabel}</bold>, l’intera cronologia verrà riletta al prossimo messaggio.",
  "Your next response will be slower and use more tokens. This task is cached for the current thinking mode. Switching to <bold>{targetLabel}</bold> means the full history gets re-read on your next message.":
    "La prossima risposta sarà più lenta e userà più token. Questa attività è memorizzata nella cache per la modalità di ragionamento attuale. Passando a <bold>{targetLabel}</bold>, l’intera cronologia verrà riletta al prossimo messaggio.",
