    "Impossibile collegare questa attività a questo computer.",
  "Computer access is off, so tasks that require a computer won’t run.":
    "L’accesso al computer è disattivato, quindi le attività che lo richiedono non verranno eseguite.",
  "This task will run on schedule once Computer access is on.":
    "Questa attività verrà eseguita secondo il programma quando l’accesso al computer sarà attivo.",
  "Permission mode is set to Auto.":
    "La modalità di autorizzazione è impostata su Auto.",
  "Skip all approvals is on.": "Salta tutte le approvazioni è attivo.",
  "Claudex runs on its own and pauses if anything looks unsafe. This includes using your connectors and apps on your computer, unless you turn them off.":
    "Claudex lavora autonomamente e si ferma se qualcosa sembra rischioso. Questo include l’uso dei connettori e delle app sul computer, a meno che tu non li disattivi.",
  "Claudex never pauses, even for unsafe actions. This includes using your connectors and apps on your computer. You can turn off individual connectors in the + menu.":
    "Claudex non si ferma mai, nemmeno per azioni rischiose. Questo include l’uso dei connettori e delle app sul computer. Puoi disattivare i singoli connettori nel menu +.",
  "Claudex will work, browse the web, and use any connectors you’ve enabled without pausing for approval. This can put your data at risk.":
    "Claudex lavorerà, navigherà sul web e userà i connettori attivati senza fermarsi per chiedere approvazione. Questo può mettere a rischio i tuoi dati.",
  "See safe use tips": "Vedi i consigli per un uso sicuro",
