  "This feature gives Claudex network access to create and analyze files, which has <a>security risks</a>. Monitor chats closely when using this feature.":
    "Questa funzione dà a Claudex accesso alla rete per creare e analizzare file, il che comporta <a>rischi per la sicurezza</a>. Monitora attentamente le chat quando la usi.",
  "Give Claudex network access to install packages and libraries in order to perform advanced data analysis, custom visualizations, and specialized file processing. Monitor chats closely as this comes with <a>security risks</a>.":
    "Concedi a Claudex l’accesso alla rete per installare pacchetti e librerie e svolgere analisi dei dati avanzate, visualizzazioni personalizzate ed elaborazioni di file specializzate. Monitora attentamente le chat, poiché comporta <a>rischi per la sicurezza</a>.",
