  "Some folders couldn’t be added.":
    "Non è stato possibile aggiungere alcune cartelle.",
  "Bypass all permission checks and let Claudex work uninterrupted. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Ignora tutti i controlli delle autorizzazioni e lascia che Claudex lavori senza interruzioni. Questa modalità è adatta a flussi di lavoro come la correzione di errori di lint o la generazione di codice standard. Consentire a Claudex di eseguire comandi arbitrari è rischioso e può causare perdita di dati, danneggiamento del sistema o esfiltrazione di dati (ad esempio tramite attacchi di prompt injection).",
