    "Lookaround e riferimenti all’indietro non sono supportati: riscrivi senza (?=, (?!, (?<=, (?<! o riferimenti come \\1",
  "Mark the part each customer fills in, like ${user_config.mydomain}":
    "Indica la parte compilata da ogni cliente, ad esempio ${user_config.mydomain}",
  "Must be 400 characters or fewer": "Deve contenere al massimo 400 caratteri",
  "Not a valid regular expression": "Espressione regolare non valida",
  "Only the subdomain may vary — end the host with your literal domain, e.g. ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$":
    "Solo il sottodominio può variare: termina l’host con il dominio letterale, ad es. ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$",
  "Pattern must end with $ so it can't match a longer host":
    "Il modello deve terminare con $ per non corrispondere a un host più lungo",
  "Pattern must start with ^https://": "Il modello deve iniziare con ^https://",
  "Remove the @ — userinfo before the host isn't allowed":
    "Rimuovi @: le informazioni utente prima dell’host non sono consentite",
