  Denied: "Negato",
  "Not requested": "Non richiesto",
  "Background computer use": "Uso del computer in background",
  "Claudex will see your whole screen and use your mouse and keyboard on it. You’ll approve the apps Claudex asks for, but on this system access can’t be limited to them, and you won’t confirm each step Claudex performs.":
    "Claudex vedrà l’intero schermo e userà mouse e tastiera. Approverai le app richieste, ma su questo sistema l’accesso non può essere limitato a esse e non confermerai ogni passaggio.",
  "Claudex will see the apps you approve and click and type in them, working in the background while you keep using your computer or taking full control of your screen. Which of those Claudex does by default is set under Settings → This computer → Computer use. You’ll approve each app, but not confirm each step Claudex performs.":
    "Claudex vedrà le app che approvi e farà clic e scriverà al loro interno, in background mentre continui a usare il computer o con il controllo completo dello schermo. Il comportamento predefinito si imposta in Impostazioni → Questo computer → Uso del computer. Approverai ogni app, ma non confermerai ogni passaggio.",
  "Claudex can now control your applications in the background without taking over your screen, and will ask your permission if Claudex needs full control of your mouse and keyboard. If you’d prefer Claudex to default to full control instead of background mode, you can change this at any time under Settings → This computer → Computer use.":
    "Claudex ora può controllare le tue app in background senza occupare lo schermo e ti chiederà il permesso se ha bisogno del controllo completo di mouse e tastiera. Se preferisci il controllo completo come predefinito, puoi cambiarlo in qualsiasi momento in Impostazioni → Questo computer → Uso del computer.",
