  "Strict sandbox mode": "Modalità sandbox rigorosa",
  "Blocks commands that can’t run inside the sandbox (ssh, for example) instead of running them outside it or asking you. Applies to new sessions.":
    "Blocca i comandi che non possono essere eseguiti nella sandbox (ad esempio ssh) invece di eseguirli fuori o chiederti. Si applica alle nuove sessioni.",
  "Available when Local sandbox is on":
    "Disponibile quando la sandbox locale è attiva",
  "Monthly spend limit": "Limite di spesa mensile",
  "{used} this month · No spend limit":
    "{used} questo mese · Nessun limite di spesa",
