  "A task that isn’t part of what a session is doing can run in its own linked session. Choose whether Claudex asks each time, keeps it in the session you typed it in, or opens a linked session for it.":
    "Un'attività non correlata può essere eseguita in una sessione collegata dedicata. Scegli se Claudex deve chiedere ogni volta, mantenerla nella sessione attuale o aprire una sessione collegata.",
  "Ask me": "Chiedimelo",
