  "This suggestion is no longer available.":
    "Questo suggerimento non è più disponibile.",
  "Delete sessions stored by your Claudex service?":
    "Eliminare le sessioni archiviate dal servizio Claudex?",
  "Your Claudex service’s copies of your Claudex Code sessions will be permanently deleted. Sessions on your computer aren’t affected. This can’t be undone.":
    "Le copie delle sessioni Claudex Code sul servizio Claudex verranno eliminate definitivamente. Le sessioni sul computer non saranno interessate. L'operazione non può essere annullata.",
  "Delete stored sessions": "Elimina sessioni archiviate",
