    "Questa impostazione può mettere a rischio i tuoi dati.",
  "Claudex will browse and interact with any website without asking. Applies to new sessions. This setting can put your data at risk.":
    "Claudex navigherà e interagirà con qualsiasi sito web senza chiedere. Si applica alle nuove sessioni. Questa impostazione può mettere a rischio i tuoi dati.",
  "Claudex will take actions without asking for your permission, including on websites you haven’t approved.":
    "Claudex eseguirà azioni senza chiederti il permesso, anche sui siti web che non hai approvato.",
