  "For this reflection to work, you’ll need to enable memory in <a>memory settings</a>.":
    "Perché questa riflessione funzioni, devi attivare la memoria nelle <a>impostazioni della memoria</a>.",
  "Search by name": "Cerca per nome",
  "Build connectors and plugins": "Creare connettori e plugin",
  "A connector is an MCP server: it speaks the Model Context Protocol over streamable HTTP, signs people in with OAuth or a token, and describes each tool’s inputs and effects plainly. A plugin bundles skills, connectors and instructions into one package. Add your connector as a custom connector under Customize → Connectors and try it in a chat before you send it with Submit to the directory.":
    "Un connettore è un server MCP: usa il Model Context Protocol su HTTP in streaming, fa accedere le persone con OAuth o un token e descrive chiaramente input ed effetti di ogni strumento. Un plugin raccoglie skill, connettori e istruzioni in un unico pacchetto. Aggiungi il tuo connettore come connettore personalizzato in Personalizza → Connettori e provalo in una chat prima di inviarlo con Invia alla directory.",
